import{_ as e,o,c as n,a2 as i}from"./chunks/framework.CgxQ0r6v.js";const p=JSON.parse('{"title":"Manual de Estudio Profundo: Evaluación 4","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_I/documentacion/I-III/Lectura_Catedra_Evaluacion_4.md","filePath":"materias/Proyecto_Sociotecnologico_I/documentacion/I-III/Lectura_Catedra_Evaluacion_4.md"}'),r={name:"materias/Proyecto_Sociotecnologico_I/documentacion/I-III/Lectura_Catedra_Evaluacion_4.md"};function t(s,a,l,c,d,u){return o(),n("div",null,[...a[0]||(a[0]=[i('<h1 id="manual-de-estudio-profundo-evaluacion-4" tabindex="-1">Manual de Estudio Profundo: Evaluación 4 <a class="header-anchor" href="#manual-de-estudio-profundo-evaluacion-4" aria-label="Permalink to &quot;Manual de Estudio Profundo: Evaluación 4&quot;">​</a></h1><h2 id="materia-proyecto-sociotecnologico-trayecto-i" tabindex="-1">Materia: Proyecto Sociotecnológico (Trayecto I) <a class="header-anchor" href="#materia-proyecto-sociotecnologico-trayecto-i" aria-label="Permalink to &quot;Materia: Proyecto Sociotecnológico (Trayecto I)&quot;">​</a></h2><h3 id="eje-tematico-la-defensa-comunitaria-e-institucional" tabindex="-1">Eje Temático: La Defensa Comunitaria e Institucional <a class="header-anchor" href="#eje-tematico-la-defensa-comunitaria-e-institucional" aria-label="Permalink to &quot;Eje Temático: La Defensa Comunitaria e Institucional&quot;">​</a></h3><hr><h2 id="🧭-introduccion-el-dia-del-veredicto" tabindex="-1">🧭 Introducción: El Día del Veredicto <a class="header-anchor" href="#🧭-introduccion-el-dia-del-veredicto" aria-label="Permalink to &quot;🧭 Introducción: El Día del Veredicto&quot;">​</a></h2><p>Todo el esfuerzo de un año académico se resume en 20 minutos de exposición. Has realizado encuestas, construido árboles lógicos, ensuciado tus manos con polvo de computadoras, formateado discos duros e impreso cientos de hojas. Ahora, tienes que pararte frente a un jurado experto y convencerlos de que tu trabajo vale el título que estás buscando.</p><p>La <strong>Defensa de Proyecto</strong> no es un interrogatorio policial, es un <strong>Intercambio de Saberes</strong>. Es el momento donde te tratas de &quot;Tú a Tú&quot; como futuro colega con los profesores de la universidad y como aliado con los líderes de la comunidad.</p><hr><h2 id="🏛️-capitulo-i-las-dos-defensas" tabindex="-1">🏛️ CAPÍTULO I: Las Dos Defensas <a class="header-anchor" href="#🏛️-capitulo-i-las-dos-defensas" aria-label="Permalink to &quot;🏛️ CAPÍTULO I: Las Dos Defensas&quot;">​</a></h2><p>El Reglamento del PSI/T de la UPTT, en sintonía con el alma del Programa Nacional de Formación (PNFI), no permite que el proyecto se evalúe solo a puertas cerradas. El proyecto tiene dos dueños, y por lo tanto, dos defensas:</p><h3 id="_1-1-la-socializacion-comunitaria" tabindex="-1">1.1 La Socialización Comunitaria <a class="header-anchor" href="#_1-1-la-socializacion-comunitaria" aria-label="Permalink to &quot;1.1 La Socialización Comunitaria&quot;">​</a></h3><p>Antes de ir a la universidad, debes presentar los resultados finales en la comunidad (generalmente en el lugar donde reparaste los equipos).</p><ul><li><strong>Público:</strong> Los líderes comunitarios, profesores de la escuela y usuarios del sistema.</li><li><strong>Tono:</strong> Empático, menos técnico y más centrado en los <em>beneficios</em> logrados.</li><li><strong>Objetivo:</strong> Obtener la firma definitiva del aval comunitario confirmando que el proyecto resolvió su problema.</li></ul><h3 id="_1-2-la-defensa-institucional-academica" tabindex="-1">1.2 La Defensa Institucional (Académica) <a class="header-anchor" href="#_1-2-la-defensa-institucional-academica" aria-label="Permalink to &quot;1.2 La Defensa Institucional (Académica)&quot;">​</a></h3><p>Es la presentación formal en la UPTT.</p><ul><li><strong>Público:</strong> El Tutor Técnico, el Tutor Académico y el Jurado Evaluador de la UPSIT.</li><li><strong>Tono:</strong> Estrictamente técnico, académico y metodológico.</li><li><strong>Objetivo:</strong> Demostrar tu dominio en Informática Aplicada, el Enfoque del Marco Lógico y la programación/soporte de hardware.</li></ul><hr><h2 id="🧩-capitulo-ii-anatomia-de-la-presentacion-exitosa" tabindex="-1">🧩 CAPÍTULO II: Anatomía de la Presentación Exitosa <a class="header-anchor" href="#🧩-capitulo-ii-anatomia-de-la-presentacion-exitosa" aria-label="Permalink to &quot;🧩 CAPÍTULO II: Anatomía de la Presentación Exitosa&quot;">​</a></h2><p>Para la defensa institucional, usarás láminas de presentación (Diapositivas / Slides).</p><h3 id="_2-1-reglas-de-oro-de-las-laminas" tabindex="-1">2.1 Reglas de Oro de las Láminas <a class="header-anchor" href="#_2-1-reglas-de-oro-de-las-laminas" aria-label="Permalink to &quot;2.1 Reglas de Oro de las Láminas&quot;">​</a></h3><ol><li><strong>La Regla del 6x6:</strong> Nunca más de 6 líneas de texto por lámina, y nunca más de 6 palabras por línea. El jurado sabe leer, no vayas a leer la pantalla. Las láminas son solo un apoyo visual.</li><li><strong>Dominio Visual:</strong> Usa esquemas, flujogramas (como el de la EAP) y fotos de tu equipo trabajando en el hardware. Las fotos hablan más que mil viñetas de texto.</li><li><strong>Equidad del Equipo:</strong> Todos los integrantes del proyecto deben exponer de manera equilibrada y fluida. Eviten decir &quot;A mi me tocó la parte 1 y a mi compañero la parte 2&quot;. Un proyecto es un solo cuerpo.</li></ol><h3 id="_2-2-estructura-del-discurso-el-guion" tabindex="-1">2.2 Estructura del Discurso (El Guion) <a class="header-anchor" href="#_2-2-estructura-del-discurso-el-guion" aria-label="Permalink to &quot;2.2 Estructura del Discurso (El Guion)&quot;">​</a></h3><p>Distribuyan el tiempo lógicamente:</p><ol><li><strong>Contexto (10%):</strong> Dónde fueron y qué problema había (Breve).</li><li><strong>Metodología (20%):</strong> Cómo usaron el Marco Lógico para planificar (Muestren sus árboles).</li><li><strong>El Corazón Técnico (50%):</strong> ¡Esta es la Informática! Expliquen con detalles qué comandos usaron, qué hardware repararon, cómo configuraron la red y qué fallas electrónicas resolvieron. <strong>El jurado de informática evaluará esto severamente.</strong></li><li><strong>Conclusión (20%):</strong> Los resultados sociales tangibles y las recomendaciones futuras.</li></ol><hr><h2 id="🏗️-capitulo-iii-manejo-de-la-ronda-de-preguntas" tabindex="-1">🏗️ CAPÍTULO III: Manejo de la Ronda de Preguntas <a class="header-anchor" href="#🏗️-capitulo-iii-manejo-de-la-ronda-de-preguntas" aria-label="Permalink to &quot;🏗️ CAPÍTULO III: Manejo de la Ronda de Preguntas&quot;">​</a></h2><p>Después de que terminan de hablar, comienza la temida &quot;ronda de preguntas&quot;.</p><ul><li><strong>Escucha antes de responder:</strong> No interrumpas al jurado.</li><li><strong>Sé honesto:</strong> Si el jurado pregunta por un componente técnico específico que no conoces, es mejor decir: <em>&quot;En el marco de nuestro proyecto, el alcance técnico no llegó hasta esa arquitectura, pero es una excelente recomendación para una fase posterior&quot;</em>, en lugar de inventar una mentira técnica que te hundirá en 5 segundos.</li><li><strong>Defiende tus decisiones:</strong> Si decidiste instalar Linux en vez de Windows (por obligación legal o técnica), ten a la mano los argumentos de la <em>Ley de Infogobierno</em> o ventajas de rendimiento para defender tu elección con propiedad profesional.</li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p><strong>Felicidades Ingeniero en Formación</strong> Si has seguido estos manuales, respetado a la comunidad y documentado todo científicamente, la defensa será un mero trámite celebratorio. Al aprobar la defensa, oficialmente has culminado el Trayecto I y te preparas para el Trayecto II, donde dejaremos los destornilladores y entraremos de lleno a la Programación de Sistemas de Información.</p></div><hr><p><strong>FIN DEL TRAYECTO I - PROYECTO SOCIOTECNOLÓGICO</strong></p>',31)])])}const g=e(r,[["render",t]]);export{p as __pageData,g as default};
